"""Lot 2 : Sourou, Soum, Liptako."""
from tales_kit import art, choice, gloss, it, quiz, scene, tale

# ------------------------------------------------------------------ Sourou
tale(41, "le-crapaud-qui-appela-la-pluie", type="conte", region="sourou", place="Tougan",
     coords=(13.07, -3.07), people="Samo", language="dioula", duration=4, age=4,
     tags=["animaux", "pluie", "pourquoi", "courage"], cover=2,
     fr=("Le crapaud qui appela la pluie", "Pourquoi il chante avant l'orage",
         "La vallée du Sourou meurt de soif. Le lion, l'éléphant et le calao échouent à faire venir la pluie. Le petit crapaud, lui, ose monter jusqu'au ciel.",
         "La taille ne fait pas le courage : le plus petit peut sauver tout le monde."),
     en=("The Toad Who Called the Rain", "Why it sings before the storm",
         "The Sourou valley is dying of thirst. The lion, the elephant and the hornbill fail to bring the rain. The little toad dares to climb up to the sky.",
         "Size does not make courage: the smallest can save everyone."),
     scenes=[
         scene(art("day", "sahel", it("sun", 80, 320, 1.4), it("toad", 40, s=1.6), it("lion", 64, s=0.7), it("elephant", 84, s=0.6), it("baobab", 14, 26, c="bare")),
               "Une année, la pluie ne vint pas sur la vallée du Sourou. Le fleuve n'était plus qu'un filet d'eau, et les animaux tinrent une grande assemblée sous le baobab.",
               "One year, the rain did not come to the Sourou valley. The river was no more than a trickle, and the animals held a great assembly under the baobab."),
         scene(art("dusk", "sahel", it("lion", 30, s=0.8), it("elephant", 56, s=0.7), it("bird-small", 76, 60), it("cloud", 60, 280)),
               "Le lion rugit vers le ciel : rien. L'éléphant barrit de toutes ses forces : rien. Le calao vola jusqu'aux nuages mais redescendit, épuisé. Alors une toute petite voix dit : « Laissez-moi essayer. »",
               "The lion roared at the sky: nothing. The elephant trumpeted with all his might: nothing. The hornbill flew up to the clouds but came back down, exhausted. Then a tiny voice said: \"Let me try.\"",
               choice(("Qui a parlé ?", "Who spoke?"),
                      [("Le petit crapaud", "The little toad"), ("La hyène", "The hyena")], 0,
                      ("Tout le monde éclata de rire… sauf la tortue.", "Everyone burst out laughing… except the tortoise."))),
         scene(art("night", "rocks", it("moon", 76, 300), it("toad", 46, 120, 1.4), it("cloud", 40, 260, c="storm"), it("cloud", 66, 280, c="storm"), it("rock", 30)),
               "Le crapaud grimpa sur le plus haut rocher et chanta toute la nuit : « Krou, krou, pluie, viens ! » Sa voix était si sincère que le ciel l'entendit. Les nuages se rassemblèrent au-dessus de la vallée.",
               "The toad climbed onto the highest rock and sang all night: \"Kroo, kroo, rain, come!\" His voice was so sincere that the sky heard him. The clouds gathered over the valley."),
         scene(art("day", "river", it("rain", 50, 300), it("cloud", 40, 270), it("toad", 30, s=1.3), it("child-up", 60), it("field", 82, 20, 0.6)),
               "La pluie tomba enfin, abondante. Les champs reverdirent et le Sourou se remplit. Depuis ce jour, quand l'orage approche, les crapauds chantent les premiers, pour rappeler au ciel sa promesse.",
               "At last the rain fell, plentiful. The fields turned green again and the Sourou filled up. Since that day, when a storm approaches, the toads sing first, to remind the sky of its promise."),
     ],
     quizzes=[
         quiz(("Qui a réussi à faire venir la pluie ?", "Who managed to bring the rain?"),
              [("Le crapaud", "The toad"), ("Le lion", "The lion"), ("L'éléphant", "The elephant")], 0),
         quiz(("Quand les crapauds chantent-ils ?", "When do the toads sing?"),
              [("Avant l'orage", "Before the storm"), ("À midi", "At noon"), ("En hiver seulement", "Only in winter")], 0),
     ],
     glossary=[gloss("Sourou", "fr", "Rivière et vallée du nord-ouest du Burkina, connues pour leurs cultures irriguées.", "A river and valley in north-western Burkina, known for irrigated farming.")],
     source=("Conte étiologique répandu dans les savanes d'Afrique de l'Ouest (le crapaud et la pluie). Version écrite pour KIBARE, située dans la vallée du Sourou, en pays samo.",
             "A \"why\" tale found across the West African savannahs (the toad and the rain). Version written for KIBARE, set in the Sourou valley, in Samo country."))

tale(42, "le-chasseur-et-la-biche-de-toma", type="conte", region="sourou", place="Toma",
     coords=(12.76, -2.89), people="Samo", language="dioula", duration=5, age=8,
     tags=["promesse", "secret", "brousse", "famille"], cover=0,
     fr=("Le chasseur et la biche de Toma", "La parole donnée",
         "Un chasseur épouse une femme d'une grande beauté, venue de la brousse. Elle ne lui demande qu'une chose : ne jamais révéler qui elle est.",
         "Un secret confié est une parole donnée : la trahir, c'est tout perdre."),
     en=("The Hunter and the Doe of Toma", "A word given",
         "A hunter marries a woman of great beauty who came from the bush. She asks only one thing: never reveal who she really is.",
         "A secret entrusted to you is a word given: betraying it means losing everything."),
     scenes=[
         scene(art("dawn", "savanna", it("sun", 16, 240), it("hunter", 30), it("antelope", 62, s=1.2), it("acacia", 84, 26)),
               "Près de Toma vivait un jeune chasseur habile. Un matin, au bord d'une mare, il vit une biche si belle qu'il n'osa pas tirer. La biche le regarda longuement, puis disparut dans les hautes herbes.",
               "Near Toma lived a skilful young hunter. One morning, beside a pond, he saw a doe so beautiful that he dared not shoot. The doe looked at him for a long time, then vanished into the tall grass."),
         scene(art("dusk", "village", it("hunter", 30), it("woman-talk", 50, c="#E69135"), it("hut", 74, 26)),
               "Le soir même, une jeune femme inconnue arriva au village. Elle épousa le chasseur et lui dit : « Je suis la biche que tu as épargnée. Ne le dis jamais à personne, ni dans la joie ni dans la colère. »",
               "That very evening, an unknown young woman came to the village. She married the hunter and told him: \"I am the doe you spared. Never tell anyone, neither in joy nor in anger.\"",
               choice(("Le chasseur gardera-t-il le secret ?", "Will the hunter keep the secret?"),
                      [("Il doit le garder", "He must keep it"), ("Il peut le dire à un ami", "He can tell a friend")], 0,
                      ("Pendant des années, il le garda…", "For years, he kept it…"))),
         scene(art("day", "village", it("sun", 84, 300), it("woman-pound", 40, c="#E69135"), it("child-up", 60), it("child", 68), it("granary", 84, 24)),
               "Le couple vécut heureux. Leur grenier était toujours plein, et leurs enfants grandirent forts et rieurs. Mais un jour, après une dispute, le chasseur cria devant tout le village : « Tais-toi, tu n'es qu'une bête de la brousse ! »",
               "The couple lived happily. Their granary was always full, and their children grew up strong and cheerful. But one day, after a quarrel, the hunter shouted in front of the whole village: \"Be quiet, you're nothing but an animal from the bush!\""),
         scene(art("dusk", "savanna", it("antelope", 60, s=1.2, flip=True), it("hunter", 26), it("bush", 80, 10), it("grass", 44)),
               "Le silence tomba. La femme le regarda avec tristesse, s'éloigna vers la brousse et redevint biche. Le chasseur la chercha toute sa vie. À Toma, on dit depuis : « Une parole lâchée ne revient jamais au nid. »",
               "Silence fell. The woman looked at him sadly, walked away into the bush and became a doe again. The hunter searched for her all his life. In Toma people have said ever since: \"A word let loose never returns to the nest.\""),
     ],
     quizzes=[
         quiz(("Qu'a demandé la femme au chasseur ?", "What did the woman ask the hunter?"),
              [("De garder son secret", "To keep her secret"), ("De lui offrir de l'or", "To give her gold"), ("De quitter le village", "To leave the village")], 0),
         quiz(("Pourquoi la femme est-elle partie ?", "Why did the woman leave?"),
              [("Le chasseur a révélé son secret", "The hunter revealed her secret"), ("Elle avait faim", "She was hungry"), ("Il pleuvait", "It was raining")], 0),
     ],
     glossary=[gloss("biche", "fr", "Femelle du cerf ; dans les contes d'Afrique de l'Ouest, l'antilope peut se changer en femme.", "A female deer; in West African tales, the antelope can turn into a woman.")],
     source=("Conte de la « femme-animal » et de l'interdit de révéler son origine, très répandu en Afrique de l'Ouest (Mandé, Samo, Mossi). Version écrite pour KIBARE, située à Toma.",
             "A tale of the \"animal wife\" and the taboo on revealing her origin, widespread in West Africa (Mandé, Samo, Mossi). Version written for KIBARE, set in Toma."))

tale(43, "les-trois-conseils-du-vieillard", type="conte", region="sourou", place="Nouna",
     coords=(12.73, -3.86), people="Marka", language="dioula", duration=5, age=8,
     tags=["sagesse", "conseils", "voyage", "patience"], cover=3,
     fr=("Les trois conseils du vieillard", "Une sagesse qui vaut de l'or",
         "Un jeune homme part chercher fortune. Au lieu d'argent, un vieillard de Nouna lui donne trois conseils. Chacun va lui sauver la vie.",
         "La sagesse des anciens vaut plus que tout l'or du monde."),
     en=("The Old Man's Three Pieces of Advice", "Wisdom worth gold",
         "A young man sets out to seek his fortune. Instead of money, an old man of Nouna gives him three pieces of advice. Each one will save his life.",
         "The wisdom of the elders is worth more than all the gold in the world."),
     scenes=[
         scene(art("day", "village", it("sun", 82, 300), it("man", 30, c="#2F3E6B"), it("elder-sit", 56), it("baobab", 82, 26, 0.9)),
               "Un jeune homme de Nouna travailla trois ans pour un vieux sage. Quand vint le moment de partir, le vieillard lui dit : « Je peux te payer en or, ou te donner trois conseils. Choisis. » Le jeune homme choisit les conseils.",
               "A young man from Nouna worked three years for an old sage. When it was time to leave, the old man said: \"I can pay you in gold, or give you three pieces of advice. Choose.\" The young man chose the advice."),
         scene(art("dusk", "savanna", it("man", 26, c="#2F3E6B"), it("elder", 50), it("bush", 70, 10), it("acacia", 86, 26)),
               "« Un : ne quitte jamais le grand chemin pour un raccourci. Deux : ne te mêle pas de ce qui ne te regarde pas. Trois : remets ta colère au lendemain. » Puis il lui donna un pain pour la route.",
               "\"One: never leave the main road for a shortcut. Two: don't meddle in what isn't your business. Three: put off your anger until the next day.\" Then he gave him a loaf for the road.",
               choice(("Le jeune homme a-t-il bien choisi ?", "Did the young man choose well?"),
                      [("Oui, la sagesse est précieuse", "Yes, wisdom is precious"), ("Non, il aurait dû prendre l'or", "No, he should have taken the gold")], 0,
                      ("On le saura en chemin…", "We'll find out on the way…"))),
         scene(art("day", "savanna", it("sun", 84, 300), it("man", 30, c="#2F3E6B"), it("man-point", 52, c="#7C3109"), it("bush", 70, 10), it("hyena", 84)),
               "En route, des voyageurs lui proposèrent un raccourci par la brousse ; il refusa. Le soir, il apprit que des brigands les avaient attaqués. Dans un village, il vit une étrange dispute et passa son chemin sans s'en mêler.",
               "On the way, travellers suggested a shortcut through the bush; he refused. That evening he learned that bandits had attacked them. In a village he saw a strange quarrel and went on his way without getting involved."),
         scene(art("night", "village", it("moon", 76, 300), it("man", 36, c="#2F3E6B"), it("woman", 56), it("child", 64), it("hut", 80, 26), it("fire", 46)),
               "Arrivé chez lui de nuit, il vit un jeune homme dans sa case et faillit éclater de colère. Mais il attendit le matin… et découvrit que c'était son propre fils, né pendant son absence ! En rompant le pain du vieillard, il y trouva l'or de ses trois années de travail.",
               "Arriving home at night, he saw a young man in his hut and almost exploded with anger. But he waited until morning… and discovered it was his own son, born while he was away! When he broke the old man's loaf, he found inside it the gold for his three years of work."),
     ],
     quizzes=[
         quiz(("Quel était le troisième conseil ?", "What was the third piece of advice?"),
              [("Remettre sa colère au lendemain", "Put off anger until the next day"), ("Courir vite", "Run fast"), ("Acheter un cheval", "Buy a horse")], 0),
         quiz(("Que contenait le pain ?", "What was inside the loaf?"),
              [("L'or de son salaire", "The gold of his wages"), ("Du miel", "Honey"), ("Une lettre", "A letter")], 0),
     ],
     glossary=[gloss("brigand", "fr", "Voleur qui attaque les voyageurs sur les routes.", "A robber who attacks travellers on the roads.")],
     source=("Conte des « trois conseils », répandu de l'Afrique de l'Ouest au Maghreb et à l'Europe, raconté notamment chez les Marka et les Dioula. Version écrite pour KIBARE, située à Nouna.",
             "The \"three pieces of advice\" tale, found from West Africa to the Maghreb and Europe, told among the Marka and Dioula. Version written for KIBARE, set in Nouna."))

# ------------------------------------------------------------------ Soum
tale(44, "les-kurumba-gens-du-commencement", type="legende", region="soum", place="Arbinda",
     coords=(14.23, -0.87), people="Kurumba", language="moore", duration=5, age=8,
     tags=["origines", "terre", "masques", "peuples"], featured=True, cover=2,
     fr=("Les Kurumba, gens du commencement", "Les maîtres de la terre du Lurum",
         "Bien avant les royaumes, les Kurumba vivaient déjà sur les terres d'Arbinda. Quand de nouveaux venus arrivent, ce sont eux qui gardent l'alliance avec la terre.",
         "Ceux qui arrivent les premiers ont le devoir de veiller sur la terre pour ceux qui viendront après."),
     en=("The Kurumba, People of the Beginning", "Masters of the land of Lurum",
         "Long before the kingdoms, the Kurumba already lived on the lands of Arbinda. When newcomers arrive, it is they who keep the alliance with the earth.",
         "Those who arrive first have the duty to watch over the land for those who come after."),
     scenes=[
         scene(art("dawn", "rocks", it("sun", 16, 240), it("rock", 40), it("elder", 30), it("antelope", 64, s=1.1), it("acacia", 86, 26)),
               "Au commencement, disent les Kurumba, les hommes et la terre ne se connaissaient pas encore. Les premiers ancêtres arrivèrent sur ces collines rocheuses, près d'Arbinda, et demandèrent à la terre la permission de s'y installer.",
               "In the beginning, say the Kurumba, people and the earth did not yet know each other. The first ancestors arrived on these rocky hills near Arbinda and asked the earth for permission to settle there."),
         scene(art("night", "rocks", it("moon", 76, 300), it("fire", 46), it("elder-sit", 30), it("calabash", 56), it("rock", 72)),
               "La terre accepta, à une condition : que les Kurumba lui offrent des sacrifices chaque saison et respectent ses interdits. C'est ainsi qu'ils devinrent les « maîtres de la terre », ceux qui parlent avec elle.",
               "The earth agreed, on one condition: that the Kurumba make offerings to it every season and respect its taboos. That is how they became the \"masters of the earth\", those who speak with it."),
         scene(art("day", "sahel", it("sun", 82, 300), it("rider", 30), it("horse", 46, s=0.9), it("elder", 66), it("hut", 84, 26)),
               "Bien plus tard, des cavaliers mossi et des bergers peuls arrivèrent dans le pays. Ils apportaient la force des armes et de grands troupeaux. Mais pour cultiver et vivre en paix, il fallait l'accord de la terre.",
               "Much later, Mossi horsemen and Fulani herders arrived in the country. They brought the strength of weapons and great herds. But to farm and live in peace, the earth's agreement was needed.",
               choice(("Vers qui les nouveaux venus doivent-ils se tourner ?", "Whom must the newcomers turn to?"),
                      [("Les Kurumba, maîtres de la terre", "The Kurumba, masters of the earth"), ("Personne", "Nobody")], 0,
                      ("Ils vinrent saluer le chef de terre kurumba…", "They came to greet the Kurumba earth chief…"))),
         scene(art("day", "village", it("sun", 84, 300), it("antelope", 30, s=1.1), it("dancer" if False else "man-up", 50, c="#7C3109"), it("drum", 66), it("child-up", 78)),
               "Ainsi se fit l'alliance : le roi gouverne, mais le chef de terre kurumba veille sur les champs et la pluie. Lors des grandes fêtes, les danseurs portent encore les cimiers en forme d'antilope, rappel du temps où tout a commencé.",
               "So the alliance was made: the king governs, but the Kurumba earth chief watches over the fields and the rain. At great festivals, dancers still wear antelope-shaped crests, in memory of the time when everything began."),
     ],
     quizzes=[
         quiz(("Que signifie « Kurumba » selon la tradition ?", "What does \"Kurumba\" mean according to tradition?"),
              [("Les gens du commencement", "The people of the beginning"), ("Les cavaliers", "The horsemen"), ("Les pêcheurs", "The fishermen")], 0),
         quiz(("Quel animal orne les cimiers des danseurs ?", "Which animal decorates the dancers' crests?"),
              [("L'antilope", "The antelope"), ("Le lion", "The lion"), ("Le crocodile", "The crocodile")], 0),
     ],
     glossary=[gloss("chef de terre", "fr", "Responsable religieux qui fait les sacrifices à la terre et veille aux interdits.", "A religious leader who makes offerings to the earth and upholds its taboos.")],
     source=("D'après les travaux anthropologiques sur les Kurumba du Lurum (B.-F. Gérard, « Un village, un peuple, un roi », IRD), qui glosent Kurumba par « gens du commencement », et les cimiers-antilopes adone. Mise en récit libre et simplifiée.",
             "Based on anthropological work on the Kurumba of Lurum (B.-F. Gérard, \"Un village, un peuple, un roi\", IRD), which glosses Kurumba as \"people of the beginning\", and on the adone antelope crests. Free, simplified retelling."))

tale(45, "le-berger-peul-et-la-hyene", type="conte", region="soum", place="Djibo",
     coords=(14.10, -1.63), people="Peuls", language="fulfulde", duration=4, age=5,
     tags=["animaux", "ruse", "troupeau", "vigilance"], cover=2,
     fr=("Le berger peul et la hyène", "La flûte de la nuit",
         "Chaque nuit, une hyène rôde autour du troupeau du jeune Hamadou. Trop petit pour se battre, il trouve une autre façon de protéger ses vaches.",
         "L'intelligence et la vigilance protègent mieux que la force."),
     en=("The Fulani Herder and the Hyena", "The night flute",
         "Every night a hyena prowls around young Hamadou's herd. Too small to fight, he finds another way to protect his cows.",
         "Intelligence and vigilance protect better than strength."),
     scenes=[
         scene(art("dusk", "sahel", it("shepherd", 30), it("cow", 52), it("cow", 66, s=0.9), it("acacia", 86, 26)),
               "Au Djelgodji, autour de Djibo, le petit Hamadou gardait seul les vaches de son père pendant la saison sèche. Le soir, il les rassemblait près d'un grand acacia.",
               "In Djelgodji, around Djibo, little Hamadou looked after his father's cows alone during the dry season. In the evening he gathered them near a great acacia."),
         scene(art("night", "sahel", it("moon", 76, 300), it("hyena", 70), it("cow", 46), it("shepherd", 24)),
               "Une nuit, des yeux brillèrent dans l'obscurité : la hyène ! Elle tournait autour du troupeau, cherchant le veau le plus faible. Hamadou n'avait qu'un bâton et une petite flûte.",
               "One night, eyes gleamed in the dark: the hyena! It circled the herd, looking for the weakest calf. Hamadou had only a stick and a small flute.",
               choice(("Que peut faire Hamadou ?", "What can Hamadou do?"),
                      [("Utiliser sa flûte", "Use his flute"), ("Se battre avec la hyène", "Fight the hyena")], 0,
                      ("Hamadou eut une idée…", "Hamadou had an idea…"))),
         scene(art("night", "sahel", it("moon", 76, 300), it("shepherd", 40), it("fire", 56), it("cow", 70), it("hyena", 90, flip=True)),
               "Il alluma un feu et joua de la flûte toute la nuit, en changeant de place sans cesse. La hyène crut qu'une foule de bergers veillaient autour du troupeau. Elle n'osa pas approcher.",
               "He lit a fire and played the flute all night, constantly changing places. The hyena thought a crowd of herders was watching over the herd. It didn't dare come near."),
         scene(art("dawn", "sahel", it("sun", 16, 240), it("shepherd", 30), it("cow", 52), it("cow", 64, s=0.9), it("elder", 82)),
               "Au matin, toutes les vaches étaient là. Son père le félicita : « Tu n'as pas la force d'un homme, mais tu en as la sagesse. » Depuis, au Djelgodji, les jeunes bergers apprennent la flûte en même temps que le troupeau.",
               "In the morning all the cows were there. His father congratulated him: \"You don't have a man's strength, but you have his wisdom.\" Since then, in Djelgodji, young herders learn the flute along with the herd."),
     ],
     quizzes=[
         quiz(("Comment Hamadou a-t-il éloigné la hyène ?", "How did Hamadou keep the hyena away?"),
              [("Avec du feu et sa flûte", "With fire and his flute"), ("Avec un fusil", "With a gun"), ("En criant", "By shouting")], 0),
         quiz(("Que gardait Hamadou ?", "What was Hamadou looking after?"),
              [("Les vaches de son père", "His father's cows"), ("Des chèvres", "Goats"), ("Un champ", "A field")], 0),
     ],
     glossary=[gloss("Djelgodji", "fr", "Pays peul autour de Djibo ; c'est aussi le nom de la province depuis 2025.", "Fulani country around Djibo; since 2025 it is also the name of the province.")],
     source=("Conte pastoral peul (le jeune berger et la hyène), raconté sous de nombreuses formes au Sahel. Version écrite pour KIBARE, située au Djelgodji.",
             "A Fulani pastoral tale (the young herder and the hyena), told in many forms across the Sahel. Version written for KIBARE, set in Djelgodji."))

tale(46, "l-antilope-qui-apprit-la-danse", type="conte", region="soum", place="Pobé-Mengao",
     coords=(13.88, -1.75), people="Kurumba", language="moore", duration=4, age=6,
     tags=["danse", "masques", "animaux", "fête"], cover=3,
     fr=("L'antilope qui apprit la danse aux hommes", "D'où vient la danse des cimiers",
         "Les hommes de Pobé ne savaient pas danser pour remercier la pluie. Une antilope, sauvée par un enfant, leur offre ses pas les plus légers.",
         "La gratitude se partage : un bienfait rendu peut devenir une fête pour tous."),
     en=("The Antelope Who Taught People to Dance", "Where the crest dance comes from",
         "The people of Pobé did not know how to dance to thank the rain. An antelope, saved by a child, gives them her lightest steps.",
         "Gratitude is shared: a kindness returned can become a celebration for all."),
     scenes=[
         scene(art("day", "rocks", it("sun", 82, 300), it("antelope", 50, s=1.2), it("rope", 54), it("child", 30), it("rock", 74)),
               "Un jour, le petit Issa trouva une antilope prise dans un piège, entre les rochers de Pobé. Elle tremblait. Malgré la faim de sa famille, Issa défit les cordes et la laissa partir.",
               "One day little Issa found an antelope caught in a trap among the rocks of Pobé. She was trembling. Despite his family's hunger, Issa undid the ropes and let her go."),
         scene(art("dusk", "rocks", it("antelope", 60, s=1.2, flip=True), it("child", 36), it("moon", 80, 290)),
               "Le soir, l'antilope revint et parla : « Tu m'as rendu la liberté. Je vais t'offrir ce que j'ai de plus précieux : ma danse. » Et elle se mit à bondir avec une grâce que l'enfant n'avait jamais vue.",
               "That evening the antelope returned and spoke: \"You gave me back my freedom. I will give you what I hold most precious: my dance.\" And she began to leap with a grace the child had never seen.",
               choice(("Que doit faire Issa ?", "What should Issa do?"),
                      [("Apprendre la danse et la partager", "Learn the dance and share it"), ("La garder pour lui seul", "Keep it to himself")], 0,
                      ("Issa apprit chaque pas, nuit après nuit…", "Issa learned every step, night after night…"))),
         scene(art("day", "village", it("sun", 84, 300), it("child-up", 40), it("man-up", 56, c="#7C3109"), it("drum", 70), it("woman-up", 82)),
               "Quand la première pluie tomba, Issa dansa devant tout le village, en imitant les bonds de l'antilope. Les anciens furent émus : « Voilà comment remercier le ciel ! » Tous apprirent la danse.",
               "When the first rain fell, Issa danced in front of the whole village, imitating the antelope's leaps. The elders were moved: \"That is how to thank the sky!\" Everyone learned the dance."),
         scene(art("day", "village", it("sun", 84, 300), it("antelope", 26, s=1.1), it("man-up", 48, c="#C9822B"), it("man-up", 62, c="#7C3109"), it("drum", 78)),
               "Pour ne jamais oublier, les sculpteurs taillèrent des cimiers en forme d'antilope que les danseurs portent sur la tête. Aujourd'hui encore, en pays kurumba, on danse ainsi lors des grandes fêtes.",
               "So as never to forget, the sculptors carved antelope-shaped crests that the dancers wear on their heads. To this day, in Kurumba country, people dance like this at great festivals."),
     ],
     quizzes=[
         quiz(("Qu'a fait Issa pour l'antilope ?", "What did Issa do for the antelope?"),
              [("Il l'a libérée d'un piège", "He freed her from a trap"), ("Il l'a chassée", "He hunted her"), ("Il l'a nourrie", "He fed her")], 0),
         quiz(("Que portent les danseurs sur la tête ?", "What do the dancers wear on their heads?"),
              [("Des cimiers en forme d'antilope", "Antelope-shaped crests"), ("Des chapeaux de paille", "Straw hats"), ("Des couronnes d'or", "Gold crowns")], 0),
     ],
     glossary=[gloss("cimier", "fr", "Sculpture portée au sommet de la tête par un danseur masqué.", "A sculpture worn on top of the head by a masked dancer.")],
     source=("Conte écrit pour KIBARE, inspiré des cimiers-antilopes (adone) et des danses cérémonielles kurumba de Pobé-Mengao (archives sonores du CREM-CNRS). Récit de création, non une tradition recueillie.",
             "A tale written for KIBARE, inspired by the Kurumba antelope crests (adone) and ceremonial dances of Pobé-Mengao (CREM-CNRS sound archives). A creative retelling, not a collected tradition."))

# ------------------------------------------------------------------ Liptako
tale(47, "les-dix-sept-vaches-du-vieux-peul", type="conte", region="liptako", place="Dori",
     coords=(14.03, -0.03), people="Peuls", language="fulfulde", duration=4, age=9,
     tags=["sagesse", "héritage", "partage", "calcul"], featured=True, cover=3,
     fr=("Les dix-sept vaches du vieux Peul", "L'héritage impossible",
         "Un vieux Peul de Dori laisse dix-sept vaches à partager entre ses trois fils selon des parts impossibles. Seul un sage, avec une vache de plus, trouve la solution.",
         "Un petit geste de générosité peut résoudre ce que la dispute rend impossible."),
     en=("The Old Fulani Man's Seventeen Cows", "The impossible inheritance",
         "An old Fulani man of Dori leaves seventeen cows to be shared among his three sons in impossible portions. Only a sage, with one more cow, finds the answer.",
         "A small act of generosity can solve what quarrelling makes impossible."),
     scenes=[
         scene(art("day", "sahel", it("sun", 82, 300), it("elder-sit", 30), it("cow", 52), it("cow", 64, s=0.9), it("cow", 76, s=0.8)),
               "Avant de mourir, un vieux berger de Dori réunit ses trois fils : « L'aîné aura la moitié de mes vaches, le deuxième le tiers, et le plus jeune le neuvième. » Il possédait dix-sept vaches.",
               "Before he died, an old herder of Dori gathered his three sons: \"The eldest will have half of my cows, the second a third, and the youngest a ninth.\" He owned seventeen cows."),
         scene(art("dusk", "sahel", it("man-point", 30, c="#2F3E6B"), it("man-talk", 50, c="#7C3109"), it("man", 66, c="#C9822B"), it("cow", 84)),
               "Les fils se disputèrent : la moitié de dix-sept, c'est huit vaches et demie ! Faut-il couper une vache en morceaux ? Le ton monta, et la famille risquait de se déchirer.",
               "The sons quarrelled: half of seventeen is eight and a half cows! Must a cow be cut into pieces? Voices rose, and the family was in danger of falling apart.",
               choice(("Que faut-il faire ?", "What should be done?"),
                      [("Demander conseil à un sage", "Ask a sage for advice"), ("Couper une vache", "Cut a cow in pieces")], 0,
                      ("Ils allèrent voir le vieux marabout du village…", "They went to see the village's old scholar…"))),
         scene(art("day", "sahel", it("sun", 84, 300), it("elder", 30), it("cow", 46, c="white"), it("man", 62, c="#2F3E6B"), it("man", 74, c="#7C3109"), it("man", 86, c="#C9822B")),
               "Le sage écouta, sourit, et ajouta sa propre vache au troupeau : « Voilà, vous en avez dix-huit. » L'aîné en prit la moitié : neuf. Le deuxième le tiers : six. Le cadet le neuvième : deux. Neuf, six et deux… dix-sept !",
               "The sage listened, smiled, and added his own cow to the herd: \"There, now you have eighteen.\" The eldest took half: nine. The second a third: six. The youngest a ninth: two. Nine, six and two… seventeen!"),
         scene(art("dusk", "sahel", it("elder", 40), it("cow", 58, c="white"), it("acacia", 84, 26), it("man-up", 20, c="#7C3109")),
               "Il restait une vache : celle du sage, qui la reprit et rentra chez lui. Les trois frères, réconciliés, comprirent que leur père leur avait laissé bien plus qu'un troupeau : une leçon de partage.",
               "One cow was left: the sage's own, which he took back home. The three brothers, reconciled, understood that their father had left them much more than a herd: a lesson in sharing."),
     ],
     quizzes=[
         quiz(("Combien de vaches le sage a-t-il ajoutées ?", "How many cows did the sage add?"),
              [("Une", "One"), ("Trois", "Three"), ("Aucune", "None")], 0),
         quiz(("Combien de vaches a reçu l'aîné ?", "How many cows did the eldest receive?"),
              [("Neuf", "Nine"), ("Huit et demie", "Eight and a half"), ("Six", "Six")], 0),
     ],
     glossary=[gloss("marabout", "fr", "Savant musulman respecté, souvent consulté pour ses conseils.", "A respected Muslim scholar, often consulted for advice.")],
     source=("Énigme d'héritage (les 17 bêtes) racontée au Sahel, au Maghreb et au Moyen-Orient, souvent avec des chameaux. Version écrite pour KIBARE, située chez les Peuls du Liptako.",
             "An inheritance riddle (the 17 animals) told across the Sahel, the Maghreb and the Middle East, often with camels. Version written for KIBARE, set among the Fulani of Liptako."))

tale(48, "le-lait-de-l-etranger", type="conte", region="liptako", place="Oursi",
     coords=(14.67, -0.45), people="Peuls", language="fulfulde", duration=4, age=6,
     tags=["hospitalité", "partage", "mare", "génies"], cover=2,
     fr=("Le lait de l'étranger", "La mare d'Oursi",
         "Au bord de la mare d'Oursi, une femme peule partage son dernier lait avec un voyageur poussiéreux. Le lendemain, ses calebasses ne se vident plus.",
         "Ce que l'on donne de bon cœur nous revient multiplié."),
     en=("The Stranger's Milk", "The pond of Oursi",
         "At the edge of the Oursi pond, a Fulani woman shares her last milk with a dusty traveller. The next day, her calabashes never run empty.",
         "What is given with a good heart comes back multiplied."),
     scenes=[
         scene(art("day", "lake", it("sun", 82, 320, 1.3), it("woman", 34, c="#E69135"), it("calabash", 44), it("cow", 66, s=0.8), it("acacia", 88, 26)),
               "C'était la fin de la saison sèche. Autour de la mare d'Oursi, l'herbe était rare et les vaches donnaient peu de lait. Fatimata n'avait plus qu'une calebasse pour nourrir ses enfants.",
               "It was the end of the dry season. Around the Oursi pond, grass was scarce and the cows gave little milk. Fatimata had only one calabash left to feed her children."),
         scene(art("dusk", "sahel", it("old-woman", 64), it("woman", 34, c="#E69135"), it("calabash", 44), it("child", 22)),
               "Un soir, un vieil homme couvert de poussière s'arrêta devant sa tente : « J'ai soif, ma fille. » Fatimata regarda la calebasse, puis ses enfants.",
               "One evening a dusty old man stopped in front of her tent: \"I'm thirsty, my daughter.\" Fatimata looked at the calabash, then at her children.",
               choice(("Que doit faire Fatimata ?", "What should Fatimata do?"),
                      [("Partager son lait", "Share her milk"), ("Le garder pour ses enfants", "Keep it for her children")], 0,
                      ("Elle lui tendit la calebasse : « L'étranger est un envoyé de Dieu. »", "She handed him the calabash: \"A stranger is sent by God.\""))),
         scene(art("night", "lake", it("moon", 76, 300), it("old-woman", 50), it("catfish", 62, 6), it("star", 30, 280)),
               "Le vieil homme but quelques gorgées et rendit la calebasse… encore pleine. Puis il marcha vers la mare et disparut dans l'eau sombre. Fatimata comprit : c'était un génie de la mare.",
               "The old man drank a few sips and gave back the calabash… still full. Then he walked to the pond and vanished into the dark water. Fatimata understood: he was a spirit of the pond."),
         scene(art("day", "sahel", it("sun", 84, 300), it("woman-up", 36, c="#E69135"), it("calabash", 46), it("child-up", 56), it("cow", 74)),
               "Jusqu'aux pluies, les calebasses de Fatimata ne se vidèrent jamais. Elle partagea son lait avec tout le campement. On dit encore à Oursi : « Le lait offert ne tarit pas. »",
               "Until the rains came, Fatimata's calabashes never ran empty. She shared her milk with the whole camp. In Oursi people still say: \"Milk given away never runs dry.\""),
     ],
     quizzes=[
         quiz(("Qui était le vieil homme ?", "Who was the old man?"),
              [("Un génie de la mare", "A spirit of the pond"), ("Un marchand", "A trader"), ("Le chef", "The chief")], 0),
         quiz(("Qu'est-il arrivé aux calebasses ?", "What happened to the calabashes?"),
              [("Elles ne se vidaient plus", "They never ran empty"), ("Elles se sont cassées", "They broke"), ("Elles ont disparu", "They disappeared")], 0),
     ],
     glossary=[gloss("mare d'Oursi", "fr", "Grande mare du Sahel burkinabè, zone humide protégée (Ramsar), vitale pour les éleveurs.", "A large pond in the Burkinabè Sahel, a protected wetland (Ramsar), vital for herders.")],
     source=("Conte d'hospitalité récompensée, répandu chez les Peuls du Sahel. Version écrite pour KIBARE, située à la mare d'Oursi (Oudalan), zone humide Ramsar.",
             "A tale of rewarded hospitality, widespread among the Fulani of the Sahel. Version written for KIBARE, set at the Oursi pond (Oudalan), a Ramsar wetland."))
